import{_ as o,r as n,o as p,c as l,e as s,a as r,s as i}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Introduction - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Including the Framework","slug":"including-the-framework","link":"#including-the-framework","children":[]},{"level":2,"title":"How AJAX Requests Work","slug":"how-ajax-requests-work","link":"#how-ajax-requests-work","children":[]},{"level":2,"title":"Usage Example","slug":"usage-example","link":"#usage-example","children":[]}],"relativePath":"2.x/ajax/introduction.md","filePath":"2.x/ajax/introduction.md"}'),c={name:"2.x/ajax/introduction.md"};function u(d,a,h,k,g,m){const t=n("pre-heading"),e=n("post-heading");return p(),l("div",null,[s(t),a[0]||(a[0]=r("h1",null,"Introduction",-1)),s(e),a[1]||(a[1]=i(`<p>October CMS includes a framework that brings a full suite of AJAX capabilities which allow you to load data from the server without a browser page refresh. The same library can be used in <a href="./../cms/themes.html">CMS themes</a> and anywhere in the <a href="./../backend/controllers-ajax.html#oc-using-ajax-handlers">back-end administration area</a>.</p><p>The AJAX framework comes in two flavors, you may either use <a href="./../ajax/javascript-api.html">the JavaScript API</a> or <a href="./../ajax/attributes-api.html">the data attributes API</a>. The data attributes API doesn&#39;t require any JavaScript knowledge to use AJAX with October.</p><p><a id="oc-including-the-framework"></a></p><h2 id="including-the-framework"><a href="#including-the-framework" class="header-anchor">#</a> Including the Framework</h2><p>The AJAX framework is optional in your <a href="./../cms/themes.html">CMS theme</a>, to use the library you should include it by placing the <code>{% framework %}</code> tag anywhere inside your <a href="./../cms/pages.html">page</a> or <a href="./../cms/layouts.html">layout</a>. This adds a reference to the October front-end JavaScript library. The library requires jQuery so it should be loaded first, for example:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>assets/javascript/jquery.js<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>theme <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The <code>{% framework %}</code> tag supports the optional <strong>extras</strong> parameter. If this parameter is specified, the tag adds StyleSheet and JavaScript files for <a href="./../ajax/extras.html">extra features</a>, including form validation and loading indicators.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> extras <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="how-ajax-requests-work"><a href="#how-ajax-requests-work" class="header-anchor">#</a> How AJAX Requests Work</h2><p>A page can issue an AJAX request either prompted by data attributes or by using JavaScript. Each request invokes an <strong>event handler</strong> -- also called an <a href="./../ajax/handlers.html">AJAX handler</a> -- on the server and can update page elements using partials. AJAX requests work best with forms, since the form data is automatically sent to the server. Here is request workflow:</p><ol><li>The client browser issues an AJAX request by providing the handler name and other optional parameters.</li><li>The server finds the <a href="./../ajax/handlers.html">AJAX handler</a> and executes it.</li><li>The handler executes the required business logic and updates the environment by injecting page variables.</li><li>The server <a href="./../ajax/update-partials.html">renders partials</a> requested by the client with the <code>update</code> option.</li><li>The server sends the response, containing the rendered partials markup.</li><li>The client-side framework updates page elements with the partials data received from the server.</li></ol><blockquote><p><strong>Note</strong>: Depending on the page context a <a href="./../cms/partials.html">CMS partial</a> or <a href="./../backend/views-partials.html">backend partial</a> view will be rendered.</p></blockquote><h2 id="usage-example"><a href="#usage-example" class="header-anchor">#</a> Usage Example</h2><p>Below is a simple example that uses the data attributes API to define an AJAX enabled form. The form will issue an AJAX request to the <strong>onTest</strong> handler and requests that the result container be updated with the <strong>mypartial</strong> partial markup.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- AJAX enabled form --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onTest<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mypartial: &#39;#myDiv&#39;<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token comment">&lt;!-- Input two values --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span> + <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value2<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token comment">&lt;!-- Action button --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Calculate<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>

<span class="token comment">&lt;!-- Result container --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><blockquote><p><strong>Note</strong>: The form data for <code>value1</code> and <code>value2</code> are automatically sent with the AJAX request.</p></blockquote><p>The <strong>mypartial</strong> partial contains markup that reads the <code>result</code> variable.</p><div class="language-twig extra-class"><pre class="language-twig"><code>The result is <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The <strong>onTest</strong> handler method accessed the form data using the <code>input</code> <a href="./../services/helpers.html#method-input">helper method</a> and the result is passed to the <code>result</code> page variable.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onTest</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value1&#39;</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The example could be read like this: &quot;When the form is submitted, issue an AJAX request to the <strong>onTest</strong> handler. When the handler finishes, render the <strong>mypartial</strong> partial and inject its contents to the <strong>#myDiv</strong> element.&quot;</p>`,21))])}const v=o(c,[["render",u]]);export{w as __pageData,v as default};
